// Источник: web-тест .qa/e2e/tests/nusach-switch/ns-02-cancel-and-replace-parallel-section.spec.ts, план .qa/e2e/specs/nusach-switch.md
// Тикет #6a86f7fdaa68 «פיתוח: החלפת נוסח בתוך התפילה» (הושלם 07.10.2026). Опора: F-37 AC1–4, S-33 AC1–5.
import { expect } from '@wdio/globals';
import { byText, byLabelStartsWith, tapText, expectVisibleText, pageCounter } from '../../helpers/ui.ts';
import { openPrayer, goToPage } from '../../helpers/nav.ts';
import { toHome } from '../../helpers/app.ts';

describe('Смена нусаха внутри молитвы', () => {
  afterEach(async () => { await toHome(); });

  it('NS-02 «ביטול» оставляет всё как было, «החלף» переносит в параллельный קטע #6a86f7fdaa68 @prod-safe', async () => {
    // 1. מנחה (אשכנזי), страница 4 из 8 — «נפילת אפים».
    await openPrayer('mincha_ashkenaz', 'מנחה');
    await goToPage(4, 8);
    await expectVisibleText('נפילת אפים');

    // 2. Меню нусаха → «ספרדי» → диалог подтверждения.
    await (await byLabelStartsWith('בחירת נוסח')).click();
    await tapText('ספרדי');
    await expectVisibleText('להחליף את התפילה לנוסח ספרד?');
    await expectVisibleText('תועבר לקטע המקביל ״נפילת אפיים״.');

    // 3. «ביטול» — экран в прежнем נוסח, та же страница (S-33 AC1).
    await tapText('ביטול');
    await expect(byText('להחליף את התפילה לנוסח ספרד?')).not.toBeDisplayed();
    await expectVisibleText('מנחה (אשכנזי)');
    expect(await pageCounter()).toBe('4 מתוך 8');

    // 4. Снова → «החלף» — מנחה (ספרדי), параллельный קטע «נפילת אפיים», 6 из 11 (F-37 AC2–4).
    await (await byLabelStartsWith('בחירת נוסח')).click();
    await tapText('ספרדי');
    await tapText('החלף');
    await expectVisibleText('מנחה (ספרדי)');
    expect(await pageCounter()).toBe('6 מתוך 11');
    await expectVisibleText('נפילת אפיים');

    // Вернуть אשכנזי (профиль не менялся — S-33 AC3), чтобы не влиять на другие тесты.
    await (await byLabelStartsWith('בחירת נוסח')).click();
    await tapText('אשכנזי');
    const replace = await byText('החלף');
    if (await replace.isDisplayed().catch(() => false)) await replace.click();
    await expectVisibleText('מנחה (אשכנזי)');
  });
});
